# Compute the 10,000th prime
import math

def nth_prime(n):
    # Estimate an upper bound for the nth prime (n * (ln n + ln ln n) for n >= 6)
    k = n
    bound = int(k * (math.log(k) + math.log(math.log(k)))) + 100
    sieve = bytearray(b'\x01') * (bound + 1)
    sieve[0:2] = b'\x00\x00'
    for i in range(2, int(bound**0.5) + 1):
        if sieve[i]:
            sieve[i*i::i] = bytearray(len(sieve[i*i::i]))
    count = 0
    for p in range(2, bound + 1):
        if sieve[p]:
            count += 1
            if count == n:
                return p

